SELECT id, amount, txn_time, is_flagged, SUM(amount) OVER (PARTITION BY merchant ORDER BY txn_time, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS cumulative_amount, AVG(amount) OVER (PARTITION BY txn_type, merchant ORDER BY amount, id ROWS BETWEEN 5 PRECEDING AND CURRENT ROW) AS amount_avg_5, SUM(amount) OVER (ORDER BY txn_time, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS cumulative_amount_2, NTILE(5) OVER (ORDER BY amount DESC, id) AS amount_bucket FROM transactions;
